function data(key){if(BAHR_DATA[key])return Promise.resolve(BAHR_DATA[key]);if(loads.has(key))return loads.get(key);const p=new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='data/'+key+'.js';s.onload=()=>BAHR_DATA[key]?resolve(BAHR_DATA[key]):reject(Error('Incomplete data: '+key));s.onerror=()=>{loads.delete(key);s.remove();reject(Error('Could not load this part of the edition. Reconnect and try again.'));};document.head.append(s);});loads.set(key,p);return p;}
async function record(id){if(records.has(id))return records.get(id);const m=byId.get(id);if(!m)throw Error('Passage not found.');const group=await data(m.chunk);group.forEach(r=>records.set(r.id,r));return records.get(id);}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),4300);}
