function errorPanel(err){sheet('This page could not open','<p>'+E(err.message||err)+'</p><button data-action="retry">Try again</button>');}
function page(title,intro='',body='',wide=true){setTitle(title);$('#main').innerHTML='<section class="page '+(wide?'':'narrow')+'"><div class="breadcrumbs"><a href="#/home">Al-Kashshāf</a> / '+E(title)+'</div><header class="page-head"><span class="eyebrow">AL-KASHSHĀF · AVAILABLE SŪRAHS</span><h1>'+E(title)+'</h1>'+(intro?'<p class="intro">'+intro+'</p>':'')+'</header>'+body+'</section>';}
function visiblePlace(){if(view!=='read')return null;const elements=$$('.passage [data-anchor]');let el=elements.find(x=>x.getBoundingClientRect().bottom>110&&x.getBoundingClientRect().width>0);if(!el)el=$('.passage');if(!el)return null;const unit=el.closest('.passage');return{r:unit?.dataset.record||current,anchor:el.id,offset:el.getBoundingClientRect().top,lang:el.closest('[data-lang]')?.dataset.lang||'en'};}
function restorePlace(p){if(!p)return;const el=document.getElementById(p.anchor)||document.getElementById('unit-'+p.r);if(el)window.scrollBy(0,el.getBoundingClientRect().top-(p.offset??100));}
function applyPrefs(){let theme=prefs.theme;if(theme==='system')theme=matchMedia('(prefers-color-scheme:dark)').matches?'night':'horizon';document.documentElement.dataset.theme=theme;for(const [k,v] of Object.entries({'--en-size':prefs.enSize+'px','--ar-size':prefs.arSize+'px','--leading':prefs.leading}))document.documentElement.style.setProperty(k,v);document.body.classList.remove('tier-reading','tier-study','tier-scholarly','focus-normal','focus-quiet','focus-immersive');document.body.classList.add('tier-'+prefs.tier,'focus-'+(view==='read'?prefs.focus:'normal'));document.body.classList.toggle('no-ar',!prefs.ar);document.body.classList.toggle('tibi-off',prefs.tibi===false);document.querySelectorAll('[data-setting="tibi"]').forEach(x=>x.checked=prefs.tibi!==false);document.body.classList.toggle('no-en',!prefs.en);document.body.classList.toggle('en-first',prefs.order==='en');document.body.classList.toggle('continuous-prose',prefs.structure==='prose');document.body.classList.toggle('markers-off',!prefs.markers);$$('[data-language]').forEach(x=>x.setAttribute('aria-pressed',String(prefs[x.dataset.language])));if($('#focus-label'))$('#focus-label').textContent=prefs.focus[0].toUpperCase()+prefs.focus.slice(1);window.BahrUI?.sync();$$('[data-tier]').forEach(x=>x.setAttribute('aria-pressed',String(x.dataset.tier===prefs.tier)));}
