function settings(){const select=(key,opts)=>'<select data-setting="'+key+'" aria-label="'+key+'">'+opts.map(([v,l])=>'<option value="'+v+'" '+(prefs[key]===v?'selected':'')+'>'+l+'</option>').join('')+'</select>';sheet('Reading settings','<div class="setting-group"><h3>Reading depth</h3><div class="segmented">'+['reading','study','scholarly'].map(t=>'<button data-tier="'+t+'" aria-pressed="'+(prefs.tier===t)+'">'+t[0].toUpperCase()+t.slice(1)+'</button>').join('')+'</div><p class="small" style="margin-top:12px">The author’s text stays complete. Study adds explanatory apparatus; Scholarly adds source and critical tools.</p></div><div class="setting-group"><h3>Focus & structure</h3><label>Focus '+select('focus',[['normal','Normal'],['quiet','Quiet'],['immersive','Immersive']])+'</label><label>Presentation '+select('structure',[['headings','With topic headings'],['prose','Continuous prose']])+'</label><label>Reading scope '+select('scope',[['passage','One passage'],['continuous','Continuous passages']])+'</label><label>Selective study '+select('topic',[['all','Complete text'],...Object.entries(types)])+'</label><p class="small">Topic labels are editorial unless identified as the author’s own heading. A topic filter shows a partial English view.</p></div><div class="setting-group"><h3>Languages & type</h3><label>Arabic <input type="checkbox" data-setting="ar" '+(prefs.ar?'checked':'')+'></label><label>English <input type="checkbox" data-setting="en" '+(prefs.en?'checked':'')+'></label><label>Column order '+select('order',[['ar','Arabic first'],['en','English first']])+'</label><label>Arabic marks '+select('marks',[['source','As in the source'],['unvowelled','Unvowelled display']])+'</label><label>English size <input type="range" aria-label="English font size" data-setting="enSize" min="16" max="30" value="'+prefs.enSize+'"></label><label>Arabic size <input type="range" aria-label="Arabic font size" data-setting="arSize" min="22" max="42" value="'+prefs.arSize+'"></label><label>Line spacing <input type="range" aria-label="Line spacing" data-setting="leading" min="1.4" max="2.5" step=".05" value="'+prefs.leading+'"></label><label>Reference markers <input type="checkbox" data-setting="markers" '+(prefs.markers?'checked':'')+'></label></div><div class="setting-group"><h3>Atmosphere</h3><div class="choice-grid">'+[['horizon','Open Horizon'],['light','First Light'],['night','Night Sea'],['manuscript','Maghribī Manuscript']].map(([id,label])=>'<button class="theme-choice" data-theme="'+id+'" aria-pressed="'+(prefs.theme===id)+'"><span class="swatch '+id+'"></span>'+label+'</button>').join('')+'</div><label>Follow system appearance <input type="checkbox" data-setting="system" '+(prefs.theme==='system'?'checked':'')+'></label></div><button data-action="reset-settings">Restore reading defaults</button>','settings');}
function stripMarks(s){return String(s).replace(/[\u064b-\u065f\u0670]/g,'');}
function sourceHTML(html,id,si){const t=document.createElement('template');t.innerHTML=html;t.content.querySelectorAll('script,style,iframe,object,embed').forEach(x=>x.remove());t.content.querySelectorAll('*').forEach(x=>{for(const a of [...x.attributes])if(/^on/i.test(a.name))x.removeAttribute(a.name);if(x.hasAttribute('id'))x.id='src-'+id+'-s'+si+'-'+x.id;});t.content.querySelectorAll('a').forEach(a=>{let h=a.getAttribute('href')||'';if(/javascript:/i.test(h))a.removeAttribute('href');if(h.includes('Source_Reference_Ledger'))a.setAttribute('href','#/source/'+h.split('#').pop());if(h.startsWith('#/hadith/'))a.classList.add('report-marker');});t.content.querySelectorAll('p').forEach((p,i)=>{p.id='en-'+id+'-s'+si+'-p'+(i+1);p.dataset.anchor='true';p.dataset.lang='en';});return t.innerHTML;}
