async function renderReader(id,anchor='',restore=null,token=epoch){current=id;const first=await record(id);if(token!==epoch)return;setTitle(first.title);let start=byId.get(id).index;let group=[first];if(prefs.scope==='continuous'){group=await Promise.all(catalog.map(r=>record(r.id)));if(token!==epoch)return;}
 $('#main').innerHTML='<div class="reading-progress" aria-hidden="true"><span style="width:'+((start+1)/catalog.length*100)+'%"></span></div><div class="reader-shell"><div class="reader-context"><div><a href="#/home">Al-Kashshāf</a> / Available sūrahs <span class="muted">· '+(prefs.scope==='passage'?'One passage':'Continuous reading')+'</span></div><div class="segmented" aria-label="Reading depth">'+['reading','study','scholarly'].map(t=>'<button data-tier="'+t+'" aria-pressed="'+(prefs.tier===t)+'">'+t[0].toUpperCase()+t.slice(1)+'</button>').join('')+'</div></div>'+window.KashshafRender.layerControls(prefs)+'<div id="passages">'+group.map((r,i)=>unitHTML(r,i===0)).join('')+'</div>'+(false?'<button class="load-more" data-action="load-more" data-start="'+(start+6)+'">Continue into the next passages ↓</button>':'')+'</div>';
 applyPrefs();updateDock(id);paintHighlights();if(anchor&&(/^(?:T\d|en-.*-s[2-9])/.test(anchor))&&prefs.tibi===false){prefs.tibi=true;savePrefs();}if(anchor){const el=document.getElementById(anchor)||document.getElementById('unit-'+id);requestAnimationFrame(()=>{el?.scrollIntoView({block:'start'});if(el){el.classList.add('target-flash');setTimeout(()=>el.classList.remove('target-flash'),2000);}});}else if(restore)requestAnimationFrame(()=>restorePlace(restore));else if(prefs.scope==='continuous')requestAnimationFrame(()=>document.getElementById('unit-'+id)?.scrollIntoView());else window.scrollTo(0,0);
 if(prefs.showTerms!==false)linkLexicon().catch(()=>{});lastPlace={r:id,anchor:anchor||'unit-'+id,lang:'en'};writeStore('progress',lastPlace);
}
function updateDock(id){const r=byId.get(id);if(!r)return;$('#location-label').textContent=r.title;$('#location-source').textContent=(r.index+1)+' / 123 · Source '+r.cairo;$('#previous').disabled=r.index===0;$('#next').disabled=r.index===catalog.length-1;$('#previous').dataset.target=catalog[r.index-1]?.id||'';$('#next').dataset.target=catalog[r.index+1]?.id||'';window.BahrUI?.dock(id);}
async function loadMore(button){const i=Number(button.dataset.start);button.disabled=true;button.textContent='Opening the next passages…';const group=await Promise.all(catalog.slice(i,i+6).map(x=>record(x.id)));$('#passages').insertAdjacentHTML('beforeend',group.map(r=>unitHTML(r)).join(''));if(i+6>=catalog.length)button.remove();else{button.dataset.start=i+6;button.textContent='Continue into the next passages ↓';button.disabled=false;}paintHighlights();if(prefs.showTerms!==false)linkLexicon().catch(()=>{});}
async function linkLexicon(){const lex=await data('lexicon');if(view!=='read')return;const map=new Map();for(const e of lex)for(const a of [e.lemma,e.ar,...e.aliasesAr]){map.set(N(a),e);if(!N(a).startsWith('ال'))map.set('ال'+N(a),e);}$$('.en-column .arinline,.en-column .ar-term,.en-column bdi[lang="ar"]').forEach(x=>{if(x.closest('button,a')||x.querySelector('button,a'))return;const e=map.get(N(x.textContent.trim()));if(e){const b=document.createElement('button');b.type='button';b.className='lexical';b.dataset.lex=e.id;b.lang='ar';b.dir='rtl';b.title=e.term+' · dictionary';b.innerHTML=x.innerHTML;x.replaceWith(b);}});}
async function passageNotes(id){const r=await record(id);const [notes,reports,sources,questions]=await Promise.all(['notes','reports','sources','questions'].map(data));const n=notes.filter(n=>(n.scope||[]).some(s=>s.record_id===id)||r.segments.some(s=>s.html.includes('/note/'+n.id+'"')));const h=reports.filter(h=>r.segments.some(s=>s.html.includes('/hadith/'+h.id+'"')));const src=sources.filter(s=>s.passage_record===id);const q=questions.filter(q=>q.passages.includes(id));sheet('Annotations & references','<p class="muted">'+E(r.title)+' · Source '+E(r.cairo)+'</p>'+(r.cairo_notes.length?'<h3>Source editor</h3>'+r.cairo_notes.map(n=>'<details class="cairo-note"><summary>'+E(n.id)+' · printed p. '+E(n.page)+'</summary><p class="arabic" lang="ar" dir="rtl">'+E(n.ar)+'</p><p>'+E(n.en)+'</p></details>').join(''):'')+'<h3>Translator annotations</h3>'+(n.length?n.map(n=>'<div class="result"><button data-note="'+E(n.id)+'">'+E(n.title||n.id)+'</button></div>').join(''):'<p class="muted">No current translator annotation is attached to this passage.</p>')+(h.length?'<h3>Report dossiers</h3>'+h.map(h=>'<div class="result"><button data-report="'+h.id+'">'+E(h.title)+'</button></div>').join(''):'')+(q.length?'<h3>Critical questions</h3>'+q.map(q=>'<div class="result"><button data-question="'+q.id+'">'+E(q.question)+'</button></div>').join(''):'')+(src.length?'<h3>Source occurrences</h3>'+src.map(s=>'<div class="result"><button data-source="'+s.note_id+'">'+E(s.legacy_marker)+' · '+E(s.current_status||s.working_category)+'</button></div>').join(''):''),'reference');}
function evidenceHTML(e){const quote=e.exact_arabic||e.bounded_arabic||e.arabic_quote||e.exact_relevant_text||e.arabic_anchor;return '<div class="source-evidence"><span class="eyebrow">'+E(e.author||e.witness_type||'SOURCE EVIDENCE')+'</span><h3>'+E(e.title||e.work||e.source_id||'Source')+'</h3><p class="detail">'+E(e.edition||e.printed_edition||'')+'</p><p>'+E(e.locator||e.printed_locator||'')+'</p>'+(quote?'<p class="arabic" dir="rtl" lang="ar">'+E(quote)+'</p>':'')+'<p>'+E(e.finding||e.assessment||e.evidence||e.scope||e.interpretation||'')+'</p><p class="detail">'+E(e.inspection||e.read_scope||e.inspection_status||'')+'</p>'+external(e.url||e.public_url,'Open source')+'</div>';}
async function openNote(id){const [notes,aliases]=await Promise.all([data('notes'),data('aliases')]);const original=id;id=aliases[id]||id;const n=notes.find(n=>n.id===id);if(!n){sheet('Annotation','<p>No current annotation matches '+E(original)+'.</p>');return;}sheet(n.title||id,'<span class="pill">TRANSLATOR / EDITORIAL · '+E(id)+'</span><div class="reference-text" style="margin-top:20px"><p>'+E(n.content)+'</p></div><div class="reference-source">'+E(n.source)+'</div>'+(n.limitations?'<h3>Scope of the evidence</h3><p>'+E(n.limitations)+'</p>':'')+(n.evidence||[]).map(evidenceHTML).join('')+'<h3>In the text</h3><div class="return-links">'+(n.scope||[]).map(s=>refLink(s.record_id,'en-'+s.record_id+'-s'+(s.segment_index+1),s.quran_context+' · '+s.segment_title,'en')).join('')+'</div>'+(original!==id?'<p class="muted">Earlier marker '+E(original)+' routes to this current annotation.</p>':'')+'<button data-action="close-sheet">Return to your place</button>','reference','CURRENT TRANSLATOR ANNOTATION');$('#sheet').dataset.savedReference=JSON.stringify({kind:'note',id,title:n.title||id});window.dispatchEvent(new Event('bahr-reference-open'));}
async function openReport(id){const list=await data('reports'),h=list.find(x=>x.id===id);if(!h)return errorPanel(Error('Report not found.'));sheet(h.title,'<span class="pill">'+E(h.kind||'REPORT')+' · '+E(h.loc)+'</span><p class="reference-source">'+E(h.narrator||'')+' · '+E(h.source||'')+'</p><div class="reference-text"><p class="arabic" lang="ar" dir="rtl">'+E(h.arabic)+'</p><p>'+E(h.english)+'</p></div><h3>Assessment & scope</h3><p>'+E(h.grade)+'</p><p>'+E(h.remarks)+'</p><p class="muted">'+E(h.review)+'</p>'+external(h.url,'Read the cited source')+'<hr class="rule"><button data-action="close-sheet">Return to your place</button>','reference','REPORT DOSSIER · '+id);$('#sheet').dataset.savedReference=JSON.stringify({kind:'report',id,title:h.title});window.dispatchEvent(new Event('bahr-reference-open'));}
async function openSource(id){const list=await data('sources'),s=list.find(x=>x.note_id===id);if(!s)return errorPanel(Error('Source occurrence not found.'));const urls=[s.source_url,...String(s.current_source_urls||'').split(/[\s|]+/)].filter(x=>safeURL(x));sheet('Source occurrence '+s.legacy_marker,'<span class="pill">'+E(s.note_id)+' · '+E(s.quran_range)+'</span><div class="reference-text" style="margin-top:20px"><p>'+E(s.closest_translated_passage_context)+'</p></div><h3>Current assessment</h3><p>'+E(s.current_status||s.source_check_state)+'</p><p>'+E(s.current_assessment||s.editorial_treatment)+'</p><p class="reference-source">'+E(s.current_evidence_scope)+'</p>'+(s.current_source_locators?'<h3>Source locations</h3><p>'+E(s.current_source_locators)+'</p>':'')+urls.map((u,i)=>'<p>'+external(u,'Source '+(i+1))+'</p>').join('')+'<p class="muted">Source passage starts on p. '+E(s.Cairo_print_start_page_NOT_exact_quote_page)+'. This is not an exact quotation-page attribution.</p><div class="return-links">'+refLink(s.passage_record)+'</div><button data-action="close-sheet">Return to your place</button>','reference','SOURCE REFERENCE LEDGER');$('#sheet').dataset.savedReference=JSON.stringify({kind:'source',id,title:s.legacy_marker+' · '+s.quran_range});window.dispatchEvent(new Event('bahr-reference-open'));}
async function openQuestion(id){const list=await data('questions'),q=list.find(q=>q.id===id);if(!q)return;sheet(q.question,'<span class="pill">'+E(q.id)+' · Source '+E(q.cairo_page)+'</span><p class="muted" style="margin-top:15px">'+E(q.passage)+'</p><p class="arabic reference-text" dir="rtl" lang="ar">'+E(q.arabic_lemma)+'</p><h3>Editorial assessment</h3><p>'+E(q.status)+'</p><h3>Edition treatment</h3><p>'+E(q.edition_action)+'</p><p class="muted">English reference page in the questions register: '+E(q.english_page)+'.</p><div class="return-links">'+q.passages.map(id=>refLink(id)).join('')+'</div><a class="button" href="editions/Editorial_Audit_and_Docket_XVIII.pdf">Read the editorial audit PDF</a>','reference','CRITICAL QUESTION');$('#sheet').dataset.savedReference=JSON.stringify({kind:'question',id,title:q.question});window.dispatchEvent(new Event('bahr-reference-open'));}
async function study(){const guides=await data('guides');if(view!=='study')return;page('Study guide','Thematic routes through this edition. Each theme leads back to the complete commentary and its source location.','<div class="guide-list">'+guides.map((g,i)=>'<details><summary><small>'+String(i+1).padStart(2,'0')+' &nbsp; </small>'+E(g.title)+'</summary><p class="arabic" lang="ar" dir="rtl">'+E(g.arabic_title)+'</p>'+g.items.map(it=>'<div class="guide-item"><h3>'+E(it.title)+'</h3><p class="muted">'+E(it.description||'')+'</p>'+refs(it.references.flatMap(x=>x.target_ids||[]))+'</div>').join('')+'</details>').join('')+'</div>');}
async function indices(){const I=await data('indices');if(view!=='indices')return;page('Indices','Follow a subject, name, work, or verse of poetry to its exact English segment and source reference.','<div class="index-tabs">'+[['topics','Subjects · '+I.topics.length]].map(([k,l])=>'<button data-index="'+k+'" aria-pressed="'+(indexKind===k)+'">'+l+'</button>').join('')+'</div><label for="index-query" class="sr-only">Filter the index</label><input id="index-query" type="search" placeholder="Find an index entry" value="'+E(indexFilter)+'"><div class="index-list" id="index-results"></div>');indexResults(I);}
function indexResults(I=BAHR_DATA.indices){const needle=N(indexFilter);const rows=I[indexKind].filter(x=>!needle||N(x.h+' '+(x.subs||[]).map(s=>s.t).join(' ')).includes(needle));const links=ids=>'<div class="refs">'+ids.map(id=>{const t=I.targets[id];return t?refLink(t.r,'en-'+t.r+'-s'+(t.si+1),t.q+' · Source '+t.cairo,'en'):'';}).join('')+'</div>';$('#index-results').innerHTML='<p class="result-count">'+rows.length+' entries</p>'+rows.map(x=>'<details '+(needle?'open':'')+'><summary>'+E(x.h)+'</summary>'+(x.subs?x.subs.filter(s=>!needle||N(x.h).includes(needle)||N(s.t).includes(needle)).map(s=>'<div class="index-entry"><p>'+E(s.t)+'</p>'+links(s.refs)+'</div>').join(''):links(x.refs))+'</details>').join('');}
async function dictionary(){return window.KashshafPages.dictionary();}
function dictionaryResults(q){const n=N(q);const lex=BAHR_DATA.dictionary.filter(e=>!n||N(e.term+' '+e.ar+' '+e.root+' '+e.gloss).includes(n));$('#dictionary-results').innerHTML=lex.map(e=>'<button class="dictionary-card" data-lex="'+e.id+'"><span class="arabic" lang="ar" dir="rtl">'+E(e.ar)+'</span><strong>'+E(e.term)+'</strong><small>'+'Arabic form · '+e.occurrences.length+' occurrences</small></button>').join('')||'<p class="empty">No matching entry in the available dictionary.</p>';}
